properties.query:
let supply_events = SecurityEvent | where EventID == 4688 and ParentProcessName has_any ("update.exe", "installer.exe", "setup.exe") and ProcessName has_any ("powershell", "cmd", "wscript") | summarize supply_time=min(TimeGenerated) by Computer;
let pivot_events = SecurityEvent | where EventID == 4624 and LogonType == 3 | summarize pivot_time=min(TimeGenerated) by TargetUserName, Computer;
let staging_events = SecurityEvent | where EventID == 4663 and ObjectName has_any ("temp", "staging", "export") | summarize stage_time=min(TimeGenerated) by SubjectUserName;
supply_events | join kind=inner pivot_events on Computer | where pivot_time - supply_time between (0min .. 120min)
